  def put_concrete_inputs(threat_input : Mining_Threat_Retreat_Supervisor.Threat_Observation,
                          cargo_input : Mining_Threat_Retreat_Supervisor.Cargo_Observation,
                          capacitor_input : Mining_Threat_Retreat_Supervisor.Capacitor_Observation,
                          request_input : Mining_Threat_Retreat_Supervisor.Request_Observation,
                          mining_availability_input : Mining_Threat_Retreat_Supervisor.Mining_Availability_Observation,
                          defense_availability_input : Mining_Threat_Retreat_Supervisor.Defense_Availability_Observation,
                          retreat_availability_input : Mining_Threat_Retreat_Supervisor.Retreat_Availability_Observation,
                          service_progress_input : Mining_Threat_Retreat_Supervisor.Service_Progress_Observation): Unit = {
    put_threat_input(threat_input)
    put_cargo_input(cargo_input)
    put_capacitor_input(capacitor_input)
    put_request_input(request_input)
    put_mining_availability_input(mining_availability_input)
    put_defense_availability_input(defense_availability_input)
    put_retreat_availability_input(retreat_availability_input)
    put_service_progress_input(service_progress_input)
