  /** helper function to check Principal_Decision_Owner_supervisor_process_principal_decision_owner's
   * output ports.  Use named arguments to check subsets of the output ports.
   * @param mining_decision method that will be called with the value of the outgoing data
   *        port 'mining_decision'.
   * @param defense_decision method that will be called with the value of the outgoing data
   *        port 'defense_decision'.
   * @param movement_service_decision method that will be called with the value of the outgoing data
   *        port 'movement_service_decision'.
   * @param phase_decision method that will be called with the value of the outgoing data
   *        port 'phase_decision'.
   * @param fault_decision method that will be called with the value of the outgoing data
   *        port 'fault_decision'.
   */
  def check_concrete_output(mining_decision: Mining_Threat_Retreat_Supervisor.Mining_Command.Type => B,
                            defense_decision: Mining_Threat_Retreat_Supervisor.Defense_Command.Type => B,
                            movement_service_decision: Mining_Threat_Retreat_Supervisor.Movement_Service_Command.Type => B,
                            phase_decision: Mining_Threat_Retreat_Supervisor.Operational_Phase.Type => B,
                            fault_decision: Mining_Threat_Retreat_Supervisor.Input_Fault.Type => B): Unit = {
    var testFailures: ISZ[ST] = ISZ()

    val mining_decisionValue: Mining_Threat_Retreat_Supervisor.Mining_Command.Type = get_mining_decision().get
    if(!mining_decision(mining_decisionValue)) {
      testFailures = testFailures :+ st"'mining_decision' did not match expected: value of the outgoing data port is ${mining_decisionValue}"
    }
    val defense_decisionValue: Mining_Threat_Retreat_Supervisor.Defense_Command.Type = get_defense_decision().get
    if(!defense_decision(defense_decisionValue)) {
      testFailures = testFailures :+ st"'defense_decision' did not match expected: value of the outgoing data port is ${defense_decisionValue}"
    }
    val movement_service_decisionValue: Mining_Threat_Retreat_Supervisor.Movement_Service_Command.Type = get_movement_service_decision().get
    if(!movement_service_decision(movement_service_decisionValue)) {
      testFailures = testFailures :+ st"'movement_service_decision' did not match expected: value of the outgoing data port is ${movement_service_decisionValue}"
    }
    val phase_decisionValue: Mining_Threat_Retreat_Supervisor.Operational_Phase.Type = get_phase_decision().get
    if(!phase_decision(phase_decisionValue)) {
      testFailures = testFailures :+ st"'phase_decision' did not match expected: value of the outgoing data port is ${phase_decisionValue}"
    }
    val fault_decisionValue: Mining_Threat_Retreat_Supervisor.Input_Fault.Type = get_fault_decision().get
    if(!fault_decision(fault_decisionValue)) {
      testFailures = testFailures :+ st"'fault_decision' did not match expected: value of the outgoing data port is ${fault_decisionValue}"
    }

    assert(testFailures.isEmpty, st"${(testFailures, "\n")}".render)
  }


